import type { Readable } from 'node:stream';

/** Where attachment bytes live. Keys are random UUIDs generated by StorageService. */
export interface StorageDriver {
  /** Stores bytes under a new key; must not overwrite an existing object. */
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  /** Opens a stored object, or returns null if it doesn't exist. */
  open(key: string): Promise<Readable | null>;
  /** Deletes objects; missing keys are ignored. */
  remove(keys: string[]): Promise<void>;
}

const KEY_PATTERN = /^[0-9a-f-]{36}$/;

/** Keys are UUIDs we generated, so anything else (e.g. a path) is a bug or an attack. */
export function assertStorageKey(key: string): void {
  if (!KEY_PATTERN.test(key)) throw new Error('Invalid storage key');
}
